bench_run = function(d) {
	group_stat_icnp = function(y_L, y_R, requested_stat, tau = NULL) {
		usable = is.finite(y_L) & y_L >= 0 & !is.na(y_R) & y_R >= y_L
		if (sum(usable) < 2L) return(NA_real_)
		y_L = y_L[usable]
		y_R = y_R[usable]
		if (is.null(tau)) tau = EDI:::turnbull_arm_horizon(y_L, y_R)
		fit = tryCatch(icenReg::ic_np(cbind(y_L, y_R)), error = function(e) NULL)
		if (is.null(fit)) return(NA_real_)
		intmap = fit$T_bull_Intervals
		pf = as.numeric(fit$p_hat)
		ord = order(intmap[1, ])
		L_k = as.numeric(intmap[1, ord])
		R_k = as.numeric(intmap[2, ord])
		pf = pf[ord]
		surv_after = 1 - cumsum(pf)
		if (requested_stat == "median") {
			idx = which(surv_after <= 0.5 + sqrt(.Machine$double.eps))
			if (length(idx) == 0L) return(NA_real_)
			k = idx[1L]
			if (!is.finite(R_k[k])) return(NA_real_)
			return(as.numeric((L_k[k] + R_k[k]) / 2))
		}
		if (!is.finite(tau)) return(NA_real_)
		times = c(0, L_k)
		surv_vals = c(1, surv_after)
		keep_t = times < tau
		times = times[keep_t]
		surv_vals = surv_vals[keep_t]
		if (length(times) < 1L) return(NA_real_)
		times = c(times, tau)
		area = 0
		for (i in seq_len(length(times) - 1L)) area = area + surv_vals[i] * (times[i + 1L] - times[i])
		as.numeric(area)
	}
	stat_diff_icnp = function(y_L, y_R, w, requested_stat) {
		idx_t = w == 1
		idx_c = w == 0
		tau = NULL
		if (requested_stat == "restricted_mean") {
			tau = min(EDI:::turnbull_arm_horizon(y_L[idx_t], y_R[idx_t]), EDI:::turnbull_arm_horizon(y_L[idx_c], y_R[idx_c]))
		}
		stat_t = group_stat_icnp(y_L[idx_t], y_R[idx_t], requested_stat, tau)
		stat_c = group_stat_icnp(y_L[idx_c], y_R[idx_c], requested_stat, tau)
		if (!is.finite(stat_t) || !is.finite(stat_c)) return(NA_real_)
		as.numeric(stat_t - stat_c)
	}
	c(median = stat_diff_icnp(d$y_L, d$y_R, d$w, "median"),
		rmst = stat_diff_icnp(d$y_L, d$y_R, d$w, "restricted_mean"))
}
